  mask.querySelector('.sd-close').onclick = () => mask.remove();
  const tabs = [['cast', '\u89D2\u8272'], ['player', '\u73A9\u5BB6'], ['mood', '\u60C5\u7EEA'], ['rule', '\u683C\u5F0F'], ['gallery', '\u56FE\u7247'], ['io', '\u5BFC\u5165\u5BFC\u51FA']];
